workbox_routing_registerRoute(({ url }) => /\.(?:mp4|mov|webm|m4v)$/i.test(url.pathname), new workbox_strategies_CacheFirst({ "cacheName":"remote-video-assets", plugins: [new workbox_range_requests_RangeRequestsPlugin(), new workbox_expiration_ExpirationPlugin({ maxEntries: 48, maxAgeSeconds: 86400 })] }), 'GET');
